 12→}
 13→
 14→// LearningEntry represents a single learning from a session.
 15→type LearningEntry struct {
 16→	Scope   string // "repo", "workflow", "code"
 17→	Finding string
 18→	Path    string
 19→}
 20→
 21→// frictionThemeKeywords maps theme names to their detection keywords.
 22→// Order matters: first match wins.
 23→var frictionThemeKeywords = []struct {
 24→	theme    string
 25→	keywords []string
 26→}{
 27→	{"lint", []string{"lint", "golangci", "linter"}},
 28→	{"import", []string{"import"}},
 29→	{"compile", []string{"compile", "build error", "compilation"}},
 30→	{"format", []string{"format", "fmt", "gofmt"}},
 31→	{"test", []string{"test", "testing"}},
 32→	{"type", []string{"type assertion", "type error", "type mismatch", "type check"}},
 33→	{"permission", []string{"permission", "denied", "unauthorized"}},
 34→	{"timeout", []string{"timeout", "timed out"}},
 35→	{"retry", []string{"retry", "retrying"}},
 36→}
 37→
 38→// classifyFriction returns the theme keyword for a friction string,
 39→// or "other" if no known keyword matches.
 40→func classifyFriction(text string) string {
 41→	lower := strings.ToLower(text)
 42→	for _, entry := range frictionThemeKeywords {
 43→		for _, kw := range entry.keywords {
 44→			if strings.Contains(lower, kw) {
 45→				return entry.theme
 46→			}
 47→		}
 48→	}
 49→	return "other"
 50→}
 51→
 52→// frictionAccumulator accumulates friction examples and affected sessions per theme.
 53→type frictionAccumulator struct {
 54→	count    int
 55→	examples []string
 56→	sessions map[string]struct{} // deduplicated session IDs
 57→}
 58→
 59→// AnalyzePatterns extracts recurring patterns from session summary data.
 60→// This is the "index phase" — it works on data already in memory from SQLite.
 61→func AnalyzePatterns(summaries []SessionSummaryData) PatternAnalysis {
 62→	if len(summaries) == 0 {
 63→		return PatternAnalysis{}
 64→	}
 65→
 66→	// Accumulate friction by theme
 67→	byTheme := make(map[string]*frictionAccumulator)
 68→
 69→	for _, s := range summaries {
 70→		for _, f := range s.Friction {
 71→			theme := classifyFriction(f)
 72→			acc, ok := byTheme[theme]
 73→			if !ok {
 74→				acc = &frictionAccumulator{
 75→					sessions: make(map[string]struct{}),
 76→				}
 77→				byTheme[theme] = acc
 78→			}
 79→			acc.count++
 80→			acc.examples = append(acc.examples, f)
 81→			if s.CheckpointID != "" {
 82→				acc.sessions[s.CheckpointID] = struct{}{}
 83→			}
 84→		}
 85→	}
 86→
 87→	// Build repeated friction list (threshold: 2+ occurrences)
 88→	var repeated []FrictionPattern
 89→	for theme, acc := range byTheme {
 90→		if acc.count < 2 {
 91→			continue
 92→		}
 93→		sessions := make([]string, 0, len(acc.sessions))
 94→		for id := range acc.sessions {
 95→			sessions = append(sessions, id)
 96→		}
 97→		repeated = append(repeated, FrictionPattern{
 98→			Theme:            theme,
 99→			Count:            acc.count,
100→			Examples:         acc.examples,
101→			AffectedSessions: sessions,
102→		})
103→	}
104→
105→	// Deduplicate learnings by scope
106→	repoSeen := make(map[string]struct{})
107→	workflowSeen := make(map[string]struct{})
108→	var repoLearnings, workflowLearnings []string
109→
110→	for _, s := range summaries {
111→		for _, l := range s.Learnings {
112→			switch l.Scope {
113→			case "repo":
114→				if _, seen := repoSeen[l.Finding]; !seen {
115→					repoSeen[l.Finding] = struct{}{}
116→					repoLearnings = append(repoLearnings, l.Finding)
117→				}
118→			case "workflow":
119→				if _, seen := workflowSeen[l.Finding]; !seen {
120→					workflowSeen[l.Finding] = struct{}{}
121→					workflowLearnings = append(workflowLearnings, l.Finding)
122→				}
123→			}
124→		}
125→	}
126→
127→	// Deduplicate open items
128→	openSeen := make(map[string]struct{})
129→	var openItems []string
130→	for _, s := range summaries {
131→		for _, item := range s.OpenItems {
132→			if _, seen := openSeen[item]; !seen {
133→				openSeen[item] = struct{}{}
134→				openItems = append(openItems, item)
135→			}
136→		}
137→	}
138→
139→	return PatternAnalysis{
140→		RepeatedFriction:  repeated,
141→		RepoLearnings:     repoLearnings,
142→		WorkflowLearnings: workflowLearnings,
143→		OpenItems:         openItems,
144→		SessionCount:      len(summaries),
145→	}
146→}
