246→// truncateString truncates s to at most maxLen bytes, appending "..." if truncated.
247→func truncateString(s string, maxLen int) string {
248→	if len(s) <= maxLen {
249→		return s
250→	}
251→	return s[:maxLen] + "..."
252→}
