284→// renderImproveTerminal writes a styled terminal view of the improvement report.
285→func renderImproveTerminal(w io.Writer, report improve.ImprovementReport) {
286→	s := termstyle.New(w)
287→
288→	fmt.Fprintln(w, s.Render(s.Bold, "Entire Improve"))
289→	fmt.Fprintf(w, "Analyzed %d sessions | %d friction points | %d patterns found\n\n",
290→		report.SessionsUsed, report.FrictionTotal, report.PatternsFound)
291→
292→	// Context Files section.
293→	fmt.Fprintln(w, s.SectionRule("Context Files"))
294→	for _, cf := range report.ContextFiles {
295→		if cf.Exists {
296→			line := fmt.Sprintf("  %s  %d bytes", cf.Type, cf.SizeBytes)
297→			fmt.Fprintln(w, s.Render(s.Bold, line))
298→		} else {
299→			line := fmt.Sprintf("  %s  missing", cf.Type)
300→			fmt.Fprintln(w, s.Render(s.Gray, line))
301→		}
302→	}
303→	fmt.Fprintln(w)
304→
305→	// Suggestions section.
306→	fmt.Fprintln(w, s.SectionRule(fmt.Sprintf("Suggestions (%d)", len(report.Suggestions))))
307→	if len(report.Suggestions) == 0 {
308→		fmt.Fprintln(w, "  No suggestions generated.")
309→	}
310→	for i, sug := range report.Suggestions {
311→		// Title line with priority.
312→		titleLine := fmt.Sprintf("  %d. %s  %s", i+1, sug.Title, sug.Priority)
313→		fmt.Fprintln(w, s.Render(s.Bold, titleLine))
314→
315→		// Category and file.
316→		metaLine := fmt.Sprintf("     %s → %s", sug.Category, sug.FileType)
317→		fmt.Fprintln(w, s.Render(s.Dim, metaLine))
318→
319→		// Description.
320→		if sug.Description != "" {
321→			fmt.Fprintf(w, "     %s\n", sug.Description)
322→		}
323→
324→		// Diff rendering.
325→		if sug.Diff != "" {
326→			fmt.Fprintln(w)
327→			renderDiff(w, s, sug.Diff)
328→		}
329→		fmt.Fprintln(w)
330→	}
331→}
