  3→import (
  4→	"context"
  5→	"database/sql"
  6→	"fmt"
  7→	"time"
  8→)
  9→
 10→// SessionRow represents a single session for insertion into the cache.
 11→// This is the denormalized view used by the CLI — callers populate it
 12→// from checkpoint.CommittedMetadata.
 13→type SessionRow struct {
 14→	CheckpointID string
 15→	SessionID    string
 16→	SessionIndex int
 17→	Agent        string
 18→	Model        string
 19→	Branch       string
 20→	CreatedAt    time.Time
 21→	InputTokens  int
 22→	CacheTokens  int
 23→	OutputTokens int
 24→	TotalTokens  int
 25→	APICallCount int
 26→	DurationMs   int64
 27→	TurnCount    int
 28→	Intent       string
 29→	Outcome      string
 30→	AgentPct     float64
 31→	// Score fields (may be zero if not yet computed)
 32→	OverallScore   float64
 33→	ScoreTokenEff  float64
 34→	ScoreFirstPass float64
 35→	ScoreFriction  float64
 36→	ScoreFocus     float64
 37→	// Denormalized arrays
 38→	FilesTouched []string
 39→	Friction     []string
 40→	Learnings    []LearningRow
 41→}
 42→
 43→// LearningRow represents a single learning entry within a session.
 44→type LearningRow struct {
 45→	Scope   string // "repo", "workflow", "code"
 46→	Finding string
 47→	Path    string // only meaningful when Scope is "code"
 48→}
 49→
 50→// GetBranchTip returns the stored branch tip hash from cache_meta,
 51→// or an empty string if it has not been set yet.
 52→func (idb *InsightsDB) GetBranchTip(ctx context.Context) (string, error) {
 53→	var tip string
 54→	err := idb.db.QueryRowContext(ctx,
 55→		"SELECT value FROM cache_meta WHERE key = ?",
 56→		"branch_tip",
 57→	).Scan(&tip)
 58→	if err == sql.ErrNoRows {
 59→		return "", nil
 60→	}
 61→	if err != nil {
 62→		return "", fmt.Errorf("get branch tip: %w", err)
 63→	}
 64→	return tip, nil
 65→}
 66→
 67→// SetBranchTip stores the branch tip hash in cache_meta.
 68→// Overwrites any previously stored value.
 69→func (idb *InsightsDB) SetBranchTip(ctx context.Context, tip string) error {
 70→	_, err := idb.db.ExecContext(ctx,
 71→		"INSERT OR REPLACE INTO cache_meta (key, value) VALUES (?, ?)",
 72→		"branch_tip",
 73→		tip,
 74→	)
 75→	if err != nil {
 76→		return fmt.Errorf("set branch tip: %w", err)
 77→	}
 78→	return nil
 79→}
 80→
 81→// HasCheckpoint returns true if any session for the given checkpoint ID
 82→// is already present in the sessions table.
 83→func (idb *InsightsDB) HasCheckpoint(ctx context.Context, checkpointID string) (bool, error) {
 84→	var count int
 85→	err := idb.db.QueryRowContext(ctx,
 86→		"SELECT COUNT(*) FROM sessions WHERE checkpoint_id = ?",
 87→		checkpointID,
 88→	).Scan(&count)
 89→	if err != nil {
 90→		return false, fmt.Errorf("check checkpoint existence: %w", err)
 91→	}
 92→	return count > 0, nil
 93→}
 94→
 95→// InsertSession inserts a session and all its denormalized data into the cache.
 96→// The insert is performed inside a single transaction so the cache remains
 97→// consistent even if the caller is interrupted mid-insert.
 98→func (idb *InsightsDB) InsertSession(ctx context.Context, row SessionRow) error {
 99→	tx, err := idb.db.BeginTx(ctx, nil)
100→	if err != nil {
101→		return fmt.Errorf("begin transaction: %w", err)
102→	}
103→	defer func() {
104→		if err != nil {
105→			_ = tx.Rollback() //nolint:errcheck // Rollback after failed tx; error is irrelevant
106→		}
107→	}()
108→
109→	if err = insertSessionRow(ctx, tx, row); err != nil {
110→		return err
111→	}
112→	if err = insertFilesTouched(ctx, tx, row); err != nil {
113→		return err
114→	}
115→	if err = insertFriction(ctx, tx, row); err != nil {
116→		return err
117→	}
118→	if err = insertLearnings(ctx, tx, row); err != nil {
119→		return err
120→	}
121→
122→	if err = tx.Commit(); err != nil {
123→		return fmt.Errorf("commit transaction: %w", err)
124→	}
125→	return nil
126→}
127→
128→func insertSessionRow(ctx context.Context, tx *sql.Tx, row SessionRow) error {
129→	_, err := tx.ExecContext(ctx, `
130→		INSERT INTO sessions (
131→			checkpoint_id, session_id, session_index,
132→			agent, model, branch, created_at,
133→			input_tokens, cache_tokens, output_tokens, total_tokens,
134→			api_call_count, duration_ms, turn_count,
135→			intent, outcome, agent_percentage,
136→			overall_score, score_token_efficiency, score_first_pass,
137→			score_friction, score_focus
138→		) VALUES (
139→			?, ?, ?,
140→			?, ?, ?, ?,
141→			?, ?, ?, ?,
142→			?, ?, ?,
143→			?, ?, ?,
144→			?, ?, ?,
145→			?, ?
146→		)`,
147→		row.CheckpointID, row.SessionID, row.SessionIndex,
148→		nullableString(row.Agent), nullableString(row.Model), nullableString(row.Branch),
149→		row.CreatedAt.UTC().Format(time.RFC3339),
150→		row.InputTokens, row.CacheTokens, row.OutputTokens, row.TotalTokens,
151→		row.APICallCount, row.DurationMs, row.TurnCount,
152→		nullableString(row.Intent), nullableString(row.Outcome), row.AgentPct,
153→		nullableFloat(row.OverallScore), nullableFloat(row.ScoreTokenEff),
154→		nullableFloat(row.ScoreFirstPass), nullableFloat(row.ScoreFriction),
155→		nullableFloat(row.ScoreFocus),
156→	)
157→	if err != nil {
158→		return fmt.Errorf("insert session row: %w", err)
159→	}
160→	return nil
161→}
162→
163→func insertFilesTouched(ctx context.Context, tx *sql.Tx, row SessionRow) error {
164→	for _, f := range row.FilesTouched {
165→		if _, err := tx.ExecContext(ctx,
166→			"INSERT INTO files_touched (checkpoint_id, session_index, file_path) VALUES (?, ?, ?)",
167→			row.CheckpointID, row.SessionIndex, f,
168→		); err != nil {
169→			return fmt.Errorf("insert files_touched: %w", err)
170→		}
171→	}
172→	return nil
173→}
174→
175→func insertFriction(ctx context.Context, tx *sql.Tx, row SessionRow) error {
176→	for _, f := range row.Friction {
177→		if _, err := tx.ExecContext(ctx,
178→			"INSERT INTO friction (checkpoint_id, session_index, text) VALUES (?, ?, ?)",
179→			row.CheckpointID, row.SessionIndex, f,
180→		); err != nil {
181→			return fmt.Errorf("insert friction: %w", err)
182→		}
183→	}
184→	return nil
185→}
186→
187→func insertLearnings(ctx context.Context, tx *sql.Tx, row SessionRow) error {
188→	for _, l := range row.Learnings {
189→		if _, err := tx.ExecContext(ctx,
190→			"INSERT INTO learnings (checkpoint_id, session_index, scope, finding, path) VALUES (?, ?, ?, ?, ?)",
191→			row.CheckpointID, row.SessionIndex, l.Scope, l.Finding, nullableString(l.Path),
192→		); err != nil {
193→			return fmt.Errorf("insert learnings: %w", err)
194→		}
195→	}
196→	return nil
197→}
198→
199→// nullableString converts an empty string to a SQL NULL value.
200→// Non-empty strings are passed through as-is.
201→func nullableString(s string) interface{} {
202→	if s == "" {
203→		return nil
204→	}
205→	return s
206→}
207→
208→// nullableFloat converts a zero float to a SQL NULL value.
209→// Non-zero floats are passed through as-is.
210→func nullableFloat(f float64) interface{} {
211→	if f == 0 {
212→		return nil
213→	}
214→	return f
215→}
