226→// sessionRowsToSummaries converts insightsdb rows into improve.SessionSummaryData values.
227→func sessionRowsToSummaries(rows []insightsdb.SessionRow) []improve.SessionSummaryData {
228→	summaries := make([]improve.SessionSummaryData, 0, len(rows))
229→	for _, r := range rows {
230→		s := improve.SessionSummaryData{
231→			CheckpointID: r.CheckpointID,
232→			Friction:     r.Friction,
233→		}
234→		for _, l := range r.Learnings {
235→			s.Learnings = append(s.Learnings, improve.LearningEntry{
236→				Scope:   l.Scope,
237→				Finding: l.Finding,
238→				Path:    l.Path,
239→			})
240→		}
241→		summaries = append(summaries, s)
242→	}
243→	return summaries
244→}
