 10→// FrictionTheme groups recurring friction entries by their text content.
 11→type FrictionTheme struct {
 12→	Text     string   `json:"text"`
 13→	Count    int      `json:"count"`
 14→	Sessions []string `json:"sessions"` // checkpoint IDs where this friction occurred
