 17→// QueryLastNSessions returns the most recent N sessions ordered by created_at DESC.
 18→// Denormalized fields (FilesTouched, Friction, Learnings) are populated.
 19→func (idb *InsightsDB) QueryLastNSessions(ctx context.Context, n int) ([]SessionRow, error) {
 20→	return idb.querySessions(ctx,
 21→		"SELECT "+sessionColumns+" FROM sessions ORDER BY created_at DESC LIMIT ?",
 22→		n,
 23→	)
 24→}
