175→// loadFromFile loads settings from a specific file path.
176→// Returns default settings if the file doesn't exist.
177→func loadFromFile(filePath string) (*EntireSettings, error) {
178→	settings := &EntireSettings{
179→		Enabled: true, // Default to enabled
180→	}
181→
182→	data, err := os.ReadFile(filePath) //nolint:gosec // path is from caller
183→	if err != nil {
184→		if os.IsNotExist(err) {
185→			return settings, nil
186→		}
187→		return nil, fmt.Errorf("%w", err)
188→	}
189→
190→	dec := json.NewDecoder(bytes.NewReader(data))
191→	dec.DisallowUnknownFields()
192→	if err := dec.Decode(settings); err != nil {
193→		return nil, fmt.Errorf("parsing settings file: %w", err)
194→	}
195→
196→	// Validate commit_linking if set
197→	if settings.CommitLinking != "" && settings.CommitLinking != CommitLinkingAlways && settings.CommitLinking != CommitLinkingPrompt {
198→		return nil, fmt.Errorf("invalid commit_linking value %q: must be %q or %q", settings.CommitLinking, CommitLinkingAlways, CommitLinkingPrompt)
199→	}
200→
201→	return settings, nil
202→}
