328→// totalTokensFromUsage flattens TokenUsage for scoring.
329→func totalTokensFromUsage(tu *agent.TokenUsage) int {
330→	if tu == nil {
331→		return 0
332→	}
333→	total := tu.InputTokens + tu.CacheCreationTokens + tu.CacheReadTokens + tu.OutputTokens
334→	if tu.SubagentTokens != nil {
335→		total += totalTokensFromUsage(tu.SubagentTokens)
336→	}
337→	return total
338→}
