360→// sessionStateBackfillTokenUsage returns the best session-level token usage to
361→// persist in session state after condensation.
362→func sessionStateBackfillTokenUsage(ctx context.Context, ag agent.Agent, agentType types.AgentType, transcript []byte, checkpointUsage *agent.TokenUsage) *agent.TokenUsage {
363→	if agentType == agent.AgentTypeCopilotCLI && len(transcript) > 0 {
364→		fullSessionUsage := agent.CalculateTokenUsage(ctx, ag, transcript, 0, "")
365→		if hasTokenUsageData(fullSessionUsage) {
366→			return fullSessionUsage
367→		}
368→		logging.Debug(ctx, "copilot-cli: full-session token read produced no data, falling back to checkpoint usage")
369→	}
370→
371→	if agentType == agent.AgentTypeCopilotCLI && hasTokenUsageData(checkpointUsage) {
372→		return checkpointUsage
373→	}
374→
375→	if checkpointUsage != nil && checkpointUsage.InputTokens > 0 {
376→		return checkpointUsage
377→	}
378→
379→	return nil
380→}
