836→// clearFilesystemPrompt removes the filesystem prompt.txt for a session.
837→// Called after condensation so subsequent checkpoints start fresh.
838→func clearFilesystemPrompt(ctx context.Context, sessionID string) {
839→	sessionDir := paths.SessionMetadataDirFromSessionID(sessionID)
840→	sessionDirAbs, err := paths.AbsPath(ctx, sessionDir)
841→	if err != nil {
842→		return
843→	}
844→	promptPath := filepath.Join(sessionDirAbs, paths.PromptFileName)
845→	_ = os.Remove(promptPath)
