847→
848→// CondenseSessionByID force-condenses a session by its ID and cleans up.
849→// This is used by "entire doctor" to salvage stuck sessions.
850→func (s *ManualCommitStrategy) CondenseSessionByID(ctx context.Context, sessionID string) error {
851→	logCtx := logging.WithComponent(ctx, "condense-by-id")
852→
853→	// Load session state
854→	state, err := s.loadSessionState(ctx, sessionID)
855→	if err != nil {
856→		return fmt.Errorf("failed to load session state: %w", err)
857→	}
858→	if state == nil {
859→		return fmt.Errorf("session not found: %s", sessionID)
860→	}
861→
862→	// Open repository
863→	repo, err := OpenRepository(ctx)
864→	if err != nil {
865→		return fmt.Errorf("failed to open repository: %w", err)
866→	}
867→
868→	// Generate a checkpoint ID
869→	checkpointID, err := id.Generate()
870→	if err != nil {
871→		return fmt.Errorf("failed to generate checkpoint ID: %w", err)
872→	}
873→
874→	// Check if shadow branch exists (required for condensation)
875→	shadowBranchName := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
876→	refName := plumbing.NewBranchReferenceName(shadowBranchName)
877→	_, refErr := repo.Reference(refName, true)
878→	hasShadowBranch := refErr == nil
879→
880→	if !hasShadowBranch {
881→		// No shadow branch means no checkpoint data to condense.
882→		// Just clean up the state file.
883→		logging.Info(logCtx, "no shadow branch for session, clearing state only",
884→			slog.String("session_id", sessionID),
885→			slog.String("shadow_branch", shadowBranchName),
886→		)
