// average computes the mean of the extracted value from a slice of scores.
func average(scores []SessionScore, extract func(SessionScore) float64) float64 {
	if len(scores) == 0 {
		return 0
	}
	sum := 0.0
	for _, s := range scores {
		sum += extract(s)
	}
	return sum / float64(len(scores))
}

