	t.Setenv("GIT_DIR", "/some/repo/.git")
	t.Setenv("GIT_WORK_TREE", "/some/repo")
	t.Setenv("GIT_INDEX_FILE", "/some/repo/.git/index")

	_, err := runner.Execute(context.Background(), "test prompt")
